//! The packaged country flags, and the texture cache that draws them.
//!
//! Ported from SDRoxide's `sdroxide-ui/src/flags.rs`
//! (https://github.com/dividebysandwich/sdroxide, GPL-3.0-or-later).
//!
//! Generated by `tools/gen_flags.py` — edit the DXCC table in
//! `src/entity_flags.rs` and re-run it rather than editing the list below.
//! The images are public domain; see `assets/flags/README.md`.
//!
//! They are compiled in rather than fetched: a decode list that only shows
//! where stations are once the network answers is a decode list that shows it
//! differently on every machine, and the panel looks nothing up to draw one.

use std::collections::HashMap;

use eframe::egui;

