/// The width of a decode row's flag cell, points: a 12-point flag at its
/// widest (1.6 × its height) and a little air. Kept when a row has no flag,
/// so the columns stay in line.
pub(crate) const CELL_W: f32 = 22.0;

/// The PNG for a flag code, if we ship one.
fn png_of(code: &str) -> Option<(&'static str, &'static [u8])> {
    let i = FLAG_PNG.binary_search_by(|(c, _)| (*c).cmp(code)).ok()?;
    Some(FLAG_PNG[i])
}

/// Whether we ship a PNG for a flag code, for the country file's tests.
#[cfg(test)]
pub(crate) fn shipped(code: &str) -> bool {
    png_of(code).is_some()
}

/// A flag's PNG as an image egui can upload: the set is palette images, some
/// with a transparent edge (Nepal's pennant), so it is expanded to RGBA here.
fn decode_png(png: &[u8]) -> Option<egui::ColorImage> {
    let mut dec = png::Decoder::new(std::io::Cursor::new(png));
    dec.set_transformations(png::Transformations::EXPAND | png::Transformations::STRIP_16);
    let mut r = dec.read_info().ok()?;
    let mut buf = vec![0; r.output_buffer_size()?];
    let info = r.next_frame(&mut buf).ok()?;
    let (w, h) = (info.width as usize, info.height as usize);
    let n = info.color_type.samples();
    let rgba: Vec<u8> = buf
        .chunks_exact(n)
        .take(w * h)
        .flat_map(|p| match n {
            1 => [p[0], p[0], p[0], 255],
            2 => [p[0], p[0], p[0], p[1]],
            3 => [p[0], p[1], p[2], 255],
            _ => [p[0], p[1], p[2], p[3]],
        })
        .collect();
    (rgba.len() == w * h * 4).then(|| egui::ColorImage::from_rgba_unmultiplied([w, h], &rgba))
}

/// The size a `tw` × `th` flag is drawn at: no taller than `h` points and no
/// wider than `1.6 * h`, keeping its own proportions.
fn fit(tw: f32, th: f32, h: f32) -> egui::Vec2 {
    // Fit inside the box rather than stretching to it: flags run from 1:1
    // (Switzerland) to 1:2 (Qatar), and a stretched one reads as wrong even
    // to somebody who could not name it.
    let scale = (h / th).min((h * 1.6) / tw);
    egui::vec2(tw * scale, th * scale)
}

/// Decoded flag textures, filled the first time each flag is drawn.
///
/// One entry per *code*, not per decode: a band full of German stations
/// uploads one 48×32 texture between them. Entries stay for the life of the
/// process — the whole set decoded at once is well under a megabyte of VRAM,
/// and a band opening is exactly when re-decoding would cost the most.
#[derive(Default)]
pub(crate) struct Flags {
    /// `None` marks a code whose PNG failed to decode, so we try it once.
    cache: HashMap<&'static str, Option<egui::TextureHandle>>,
}

impl Flags {
    /// The texture for a flag code, decoding and uploading it on first use.
    fn texture(&mut self, ctx: &egui::Context, code: &str) -> Option<&egui::TextureHandle> {
        let (code, png) = png_of(code)?;
        self.cache
            .entry(code)
            .or_insert_with(|| {
                let ci = decode_png(png)?;
                // Linear, and no mipmaps: these are drawn a shade smaller than
                // they are stored, which is the one case nearest sampling
                // turns into ragged stripes.
                Some(ctx.load_texture(format!("flag-{code}"), ci, egui::TextureOptions::LINEAR))
            })
            .as_ref()
    }

    /// Draw a flag no taller than `h` points and no wider than `1.6 * h`,
    /// keeping its own proportions, and report the box it filled.
    ///
    /// Returns `None` when there is no flag for the code — the caller decides
    /// what to put in the gap, which is usually nothing.
    pub(crate) fn show(&mut self, ui: &mut egui::Ui, code: &str, h: f32) -> Option<egui::Response> {
        let tex = self.texture(ui.ctx(), code)?;
        let [tw, th] = tex.size();
        let size = fit(tw as f32, th as f32, h);
        let img = egui::Image::new((tex.id(), size)).fit_to_exact_size(size);
        Some(ui.add(img))
    }

    /// Paint a flag `h` points tall at most into a row's cell, at its left
    /// edge and centred down it, for the lists that paint their rows rather
    /// than lay them out. Returns the box it filled, or `None` (and paints
    /// nothing, leaving the cell blank) when there is no flag for the code.
    pub(crate) fn paint(
        &mut self,
        ui: &egui::Ui,
        cell: egui::Rect,
        code: &str,
        h: f32,
    ) -> Option<egui::Rect> {
        let tex = self.texture(ui.ctx(), code)?;
        let [tw, th] = tex.size();
        let size = fit(tw as f32, th as f32, h.min(cell.height()));
        let r = egui::Rect::from_min_size(
            egui::pos2(cell.left(), cell.center().y - size.y / 2.0),
            size,
        );
        let uv = egui::Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0));
        ui.painter().with_clip_rect(cell).image(tex.id(), r, uv, egui::Color32::WHITE);
        Some(r)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every code the table names has its PNG here, and every PNG here is one
    /// the table names.
    #[test]
    fn the_table_and_the_images_agree() {
        let named = crate::entity_flags::all_codes();
        let missing: Vec<&str> = named.iter().copied().filter(|c| png_of(c).is_none()).collect();
        assert!(missing.is_empty(), "no PNG for flag codes {missing:?}");
        let unused: Vec<&str> =
            FLAG_PNG.iter().map(|(c, _)| *c).filter(|c| !named.contains(c)).collect();
        assert!(unused.is_empty(), "PNGs no entity flies: {unused:?}");
        assert!(FLAG_PNG.windows(2).all(|w| w[0].0 < w[1].0), "the list must stay sorted");
    }

    /// Every PNG decodes, within the 48×32 the generator stores them at.
    #[test]
    fn every_flag_decodes() {
        for (code, png) in FLAG_PNG {
            let img = decode_png(png).unwrap_or_else(|| panic!("{code}.png does not decode"));
            let [w, h] = img.size;
            assert!(w > 0 && h > 0 && w <= 48 && h <= 32, "{code}.png is {w}×{h}");
        }
        // Nepal's pennant keeps its transparent corner.
        let np = decode_png(png_of("NP").unwrap().1).unwrap();
        assert!(np.pixels.iter().any(|p| p.a() == 0), "Nepal lost its transparency");
    }

    #[test]
    fn an_unknown_code_has_no_flag() {
        assert!(png_of("").is_none());
        assert!(png_of("ZZ").is_none());
    }

    #[test]
    fn a_flag_fits_its_box_keeping_its_shape() {
        // A 3:2 flag (France) fills the height.
        assert_eq!(fit(48.0, 32.0, 12.0), egui::vec2(18.0, 12.0));
        // Qatar, 28:11, is held to 1.6 × the height wide.
        let q = fit(48.0, 19.0, 12.0);
        assert!((q.x - 19.2).abs() < 1e-4 && q.y < 12.0);
    }
}
